/* eslint-disable @next/next/no-img-element -- tiny pixel-art SVGs, no optimisation needed */

/**
 * Pixel-art scenery at section boundaries. Each seam is anchored to the
 * boundary and grows upward; its solid base is the colour of the section
 * below, so one scene turns into the next with no edge.
 * Seams overlap the section below by 4px so fractional heights never leave a hairline.
 * Art lives in public/scenery/, generated by scripts/scenery.py.
 */

function Seam({ className, children }: { className: string; children?: React.ReactNode }) {
  return (
    <div className="pointer-events-none relative z-[2] h-0" aria-hidden="true">
      <div className={`absolute inset-x-0 ${className}`}>{children}</div>
    </div>
  );
}

const pixel = "pixelated absolute inset-0 h-full w-full";

/** Hero (paper sky) into About (blue valley): ranges, pagoda, sun. */
export function MountainSeam() {
  return (
    <Seam className="-top-[max(300px,31.25vw)] h-[calc(max(300px,31.25vw)+4px)] overflow-hidden">
      <img src="/scenery/mountains.svg" alt="" className={pixel} />
      <img src="/scenery/mountain-clouds.svg" alt="" className={`${pixel} drift`} />
      <div className="flock absolute top-[6%] left-0">
        <span className="bird" />
        <span className="bird" style={{ left: 44, top: 18, animationDelay: "-0.2s" }} />
        <span className="bird" style={{ left: 22, top: 34, animationDelay: "-0.35s" }} />
      </div>
    </Seam>
  );
}

function Lantern({ cord, delay }: { cord: number; delay: string }) {
  return (
    <div className="sway flex flex-col items-center" style={{ animationDelay: delay }}>
      <div className="w-[3px] bg-on-surface" style={{ height: cord }} />
      <img src="/scenery/lantern.svg" alt="" className="pixelated h-[84px] w-[54px]" />
    </div>
  );
}

/** Lanterns hung from the valley floor into About's side margins. */
export function LanternSeam() {
  return (
    <Seam className="top-0 hidden justify-between px-3 min-[1400px]:flex">
      <Lantern cord={56} delay="0s" />
      <Lantern cord={96} delay="-1.6s" />
    </Seam>
  );
}

/** About (blue) into Projects (paper): a 祥云 cloud sea whose base is the paper. */
export function CloudSeam() {
  return <Seam className="cloud-sea roll-slow -top-[120px] h-[124px]" />;
}

/** Projects (paper) into Contact (sea): 海水 waves whose base is the sea. */
export function WaveSeam() {
  return <Seam className="waves roll -top-28 h-[116px]" />;
}

/** Two koi crossing the sea in opposite directions. */
export function Koi() {
  const fish = "pixelated pointer-events-none absolute left-0 h-9 w-[72px]";
  return (
    <>
      <img src="/scenery/koi.svg" alt="" aria-hidden="true" className={`koi bottom-10 ${fish}`} />
      <img src="/scenery/koi.svg" alt="" aria-hidden="true" className={`koi-back top-24 ${fish}`} />
    </>
  );
}
